import{_ as t,o as a,c as n,a2 as o}from"./chunks/framework.-EXvoMUp.js";const m=JSON.parse('{"title":"Uniqueness and clocks","description":"","frontmatter":{},"headers":[],"relativePath":"uniqueness.md","filePath":"uniqueness.md"}'),s={name:"uniqueness.md"};function i(r,e,d,c,l,h){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="uniqueness-and-clocks" tabindex="-1">Uniqueness and clocks <a class="header-anchor" href="#uniqueness-and-clocks" aria-label="Permalink to &quot;Uniqueness and clocks&quot;">​</a></h1><h2 id="within-one-generator" tabindex="-1">Within one generator <a class="header-anchor" href="#within-one-generator" aria-label="Permalink to &quot;Within one generator&quot;">​</a></h2><p>An unmasked generator never reuses its timestamp/sequence pair while that instance remains alive. When the clock moves backwards, it retains the last logical timestamp and advances the sequence. When sequence capacity is exhausted, it advances logical time by one millisecond.</p><p>This avoids blocking the event loop while waiting for the physical clock. A fixed or heavily loaded clock can leave the logical timestamp ahead of real time. Expiry uses the physical clock, so such IDs start aging when real time catches up. A timestamp that cannot fit the configured field throws instead of wrapping.</p><p>Random and entropy fields sit above the sequence field. IDs in the same millisecond are <strong>not guaranteed to increase numerically</strong>. The timestamp groups IDs chronologically; the random fields also prevent Base62 strings from being a reliable lexicographic time index.</p><h2 id="across-generators-and-restarts" tabindex="-1">Across generators and restarts <a class="header-anchor" href="#across-generators-and-restarts" aria-label="Permalink to &quot;Across generators and restarts&quot;">​</a></h2><p>Assign unique machine IDs to concurrent instances and ensure your deployment does not duplicate assignments. Machine IDs derived from network interfaces are hashes and can collide. Random selection cannot guarantee unique assignments.</p><p>The library does not persist generator state. Restarting a generator with the same machine ID can reuse timestamp/sequence pairs. Random bits reduce collision probability but do not eliminate it. Use a unique database constraint and application retry policy when absolute uniqueness matters.</p><h2 id="wall-clock-and-monotonic-time" tabindex="-1">Wall-clock and monotonic time <a class="header-anchor" href="#wall-clock-and-monotonic-time" aria-label="Permalink to &quot;Wall-clock and monotonic time&quot;">​</a></h2><p>The default uses Unix milliseconds from <code>Date.now()</code>. The 42-bit default timestamp stores values through <code>2 ** 42 - 1</code> milliseconds since the epoch.</p><p><code>useWallClock: false</code> uses Node&#39;s <code>process.hrtime.bigint()</code> converted to milliseconds. Its origin is not a portable creation date. Do not mix clocks, decode monotonic IDs as dates, or compare their age on another host. <a href="./migration.html">Migration notes</a> cover older nanosecond-based IDs.</p><h2 id="choosing-a-standard" tabindex="-1">Choosing a standard <a class="header-anchor" href="#choosing-a-standard" aria-label="Permalink to &quot;Choosing a standard&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Requirement</th><th>Hybrid ID</th></tr></thead><tbody><tr><td>Custom machine field</td><td>Configurable, 12 bits by default</td></tr><tr><td>Storage size</td><td>81 bits by default; exceeds a 64-bit integer</td></tr><tr><td>Standard UUID format</td><td>Custom integer format; not a UUID</td></tr><tr><td>Creation time and age</td><td>Wall-clock IDs with masking disabled</td></tr><tr><td>Portable layout discovery</td><td>Keep configuration separately</td></tr><tr><td>Authorization or secret tokens</td><td>Use application authorization and a separate secret-token design</td></tr></tbody></table><p>Choose a standard UUID when required by your database, tooling, or interoperability contract.</p>',14)])])}const p=t(s,[["render",i]]);export{m as __pageData,p as default};
